  `visit_ratio` decimal(8,2) DEFAULT NULL,
  `rank_no` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_period_type` (`stat_period`,`dim_type`,`rank_no`)
) ENGINE=InnoDB AUTO_INCREMENT=2905 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='疾病分布';
