DROP TABLE IF EXISTS `ads_engine_consistency`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ads_engine_consistency` (
  `id` int NOT NULL AUTO_INCREMENT,
  `metric_name` varchar(64) NOT NULL COMMENT '指标名',
  `spark_value` decimal(20,4) DEFAULT NULL COMMENT 'Spark SQL 计算结果',
  `pandas_value` decimal(20,4) DEFAULT NULL COMMENT '本地引擎 / MySQL ADS 结果',
  `diff` decimal(20,4) DEFAULT NULL COMMENT '差值',
  `is_match` tinyint NOT NULL DEFAULT '0' COMMENT '是否一致（容差 0.01）',
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_metric` (`metric_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='双引擎统计口径一致性校验';
