DROP TABLE IF EXISTS `ads_los_analysis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ads_los_analysis` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stat_period` varchar(16) NOT NULL,
  `dim_type` varchar(16) NOT NULL COMMENT '科室/天数区间/疾病类别',
  `dim_value` varchar(64) NOT NULL,
  `admission_cnt` bigint NOT NULL DEFAULT '0',
  `avg_los` decimal(8,2) DEFAULT NULL,
  `los_max` int DEFAULT NULL,
  `los_min` int DEFAULT NULL,
  `avg_cost` decimal(12,2) DEFAULT NULL,
  `total_cost` decimal(16,2) DEFAULT NULL,
  `cure_rate` decimal(8,2) DEFAULT NULL,
  `rank_no` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_period_type` (`stat_period`,`dim_type`,`rank_no`)
) ENGINE=InnoDB AUTO_INCREMENT=907 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='住院天数分析';
/*!40101 SET character_set_client = @saved_cs_client */;

