--
-- Table structure for table `ads_ml_los_prediction`
--

DROP TABLE IF EXISTS `ads_ml_los_prediction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ads_ml_los_prediction` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `adm_no` varchar(40) NOT NULL COMMENT '住院号',
  `dept_name` varchar(64) DEFAULT NULL,
  `disease_category` varchar(64) DEFAULT NULL,
  `age` int DEFAULT NULL,
  `severity` int DEFAULT NULL,
  `actual_los` int NOT NULL COMMENT '实际住院日',
  `predicted_los` decimal(8,2) DEFAULT NULL COMMENT '预测住院日',
  `residual` decimal(8,2) DEFAULT NULL COMMENT '残差（实际-预测）',
  `risk_prob` decimal(8,4) DEFAULT NULL COMMENT '超长住院风险概率',
  `risk_label` varchar(16) DEFAULT NULL COMMENT '风险等级',
  `is_long_stay` tinyint DEFAULT NULL COMMENT '实际是否超长住院(>15天)',
  PRIMARY KEY (`id`),
  KEY `idx_dept` (`dept_name`)
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='住院日预测结果（MLlib 随机森林）';
/*!40101 SET character_set_client = @saved_cs_client */;

