DROP TABLE IF EXISTS `ads_ml_metric`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ads_ml_metric` (
  `metric_id` int NOT NULL AUTO_INCREMENT,
  `task_name` varchar(64) NOT NULL COMMENT '任务名称',
  `model_name` varchar(64) NOT NULL COMMENT '模型名称',
  `task_type` varchar(16) NOT NULL COMMENT 'regression/classification',
  `metric_name` varchar(64) NOT NULL COMMENT '指标名',
  `metric_value` decimal(16,4) DEFAULT NULL COMMENT '指标值',
  `train_cnt` int DEFAULT NULL COMMENT '训练样本数',
  `test_cnt` int DEFAULT NULL COMMENT '测试样本数',
  `feature_cnt` int DEFAULT NULL COMMENT '特征数',
  `params` varchar(512) DEFAULT NULL COMMENT '超参数',
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`metric_id`),
  KEY `idx_task` (`task_name`,`model_name`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Spark MLlib 模型评估指标';
/*!40101 SET character_set_client = @saved_cs_client */;

