CREATE TABLE `ads_network_edge` (
  `edge_id` bigint NOT NULL AUTO_INCREMENT,
  `src_name` varchar(128) NOT NULL COMMENT '源疾病',
  `dst_name` varchar(128) NOT NULL COMMENT '目标疾病',
  `src_category` varchar(64) DEFAULT NULL,
  `dst_category` varchar(64) DEFAULT NULL,
  `weight` bigint NOT NULL DEFAULT '0' COMMENT '共现权重（共同患者数）',
  `rank_no` int DEFAULT NULL COMMENT '按权重排名',
  PRIMARY KEY (`edge_id`),
  KEY `idx_w` (`weight`)
) ENGINE=InnoDB AUTO_INCREMENT=401 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='疾病共现网络-边（GraphX）';
