  `weighted_degree` bigint NOT NULL DEFAULT '0' COMMENT '加权度（共现患者数合计）',
  `pagerank` decimal(12,8) DEFAULT NULL COMMENT 'PageRank 值',
  `component_id` bigint DEFAULT NULL COMMENT '连通分量（疾病簇）编号',
  `community_id` bigint DEFAULT NULL COMMENT '标签传播社区编号',
  `triangle_cnt` int DEFAULT NULL COMMENT '三角计数（局部聚集度）',
  `rank_no` int DEFAULT NULL COMMENT '按 PageRank 排名',
  PRIMARY KEY (`node_id`),
  KEY `idx_pr` (`pagerank`),
  KEY `idx_deg` (`degree`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='疾病共现网络-节点（GraphX）';
