DROP TABLE IF EXISTS `ads_overview_kpi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ads_overview_kpi` (
  `id` int NOT NULL AUTO_INCREMENT,
  `stat_period` varchar(16) NOT NULL COMMENT '统计周期：全部 / yyyy-MM',
  `reg_cnt` bigint NOT NULL DEFAULT '0' COMMENT '挂号总量',
  `visited_cnt` bigint NOT NULL DEFAULT '0' COMMENT '有效就诊挂号量',
  `visit_rate` decimal(8,2) DEFAULT NULL COMMENT '挂号就诊转化率(%)',
  `visit_cnt` bigint NOT NULL DEFAULT '0' COMMENT '门诊就诊人次',
  `admission_cnt` bigint NOT NULL DEFAULT '0' COMMENT '住院人次',
  `avg_los_days` decimal(8,2) DEFAULT NULL COMMENT '平均住院日(天)',
  `presc_amount` decimal(16,2) DEFAULT NULL COMMENT '处方总金额(元)',
  `drug_qty` bigint NOT NULL DEFAULT '0' COMMENT '药品消耗总量',
  `admission_cost` decimal(16,2) DEFAULT NULL COMMENT '住院总费用(元)',
  `avg_reg_fee` decimal(10,2) DEFAULT NULL COMMENT '次均挂号费(元)',
  `avg_visit_drug_fee` decimal(10,2) DEFAULT NULL COMMENT '次均药品费用(元)',
  `infectious_cnt` bigint NOT NULL DEFAULT '0' COMMENT '法定传染病报告例数',
  `infectious_rate` decimal(8,2) DEFAULT NULL COMMENT '法定传染病占比(%)',
  `patient_cnt` bigint NOT NULL DEFAULT '0' COMMENT '就诊患者人数(去重)',
  `dept_cnt` bigint NOT NULL DEFAULT '0' COMMENT '有业务科室数',
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_period` (`stat_period`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='总体概览KPI';
/*!40101 SET character_set_client = @saved_cs_client */;

