CREATE TABLE `desensitize_rule` (
  `rule_id` int NOT NULL AUTO_INCREMENT,
  `field_name` varchar(64) NOT NULL COMMENT '字段',
  `rule_type` varchar(64) NOT NULL COMMENT '脱敏方式',
  `method_desc` varchar(255) NOT NULL COMMENT '规则说明',
