INSERT INTO `desensitize_rule` VALUES (1,'姓名 name','保留姓氏掩码','保留姓氏，其余字符替换为 *','李建国','李**','保留姓氏便于人工核对与同姓统计，姓名主体不可识别','不可逆'),(2,'身份证号 id_card','哈希加盐 + 区间泛化','HMAC-SHA256(盐, 原值) 取前 16 位十六进制；另派生出生年份、性别、年龄段','220102199803074321','6f3a9c1d5e8b2047（保留年龄 28、性别 男、地区 220102）','去掉可还原性，仅保留统计分析必需的年龄与地域粒度','不可逆'),(3,'手机号 phone','中间四位掩码','保留前 3 位与后 4 位，第 4~7 位替换为 *','13844912308','138****2308','保留号段用于渠道/地域分析，个人无法被定位','不可逆'),(4,'家庭住址 address','向上泛化','截断到「省+市+区」三级行政区，去除门牌号、楼栋、单元、室','吉林省长春市朝阳区前进大街2699号3栋2单元501室','吉林省长春市朝阳区','满足区域分布统计，去掉可精确到户的位置信息','不可逆'),(5,'病历号 / 患者编号 patient_no','伪名化（HMAC 重映射）','HMAC-SHA256(盐, 原值) 取前 12 位，加前缀 MED 生成伪编号','P20250300001234','MED4c1e8a90b2f3','跨表一致，join 不失效；无法反查真实病历号','不可逆'),(6,'电子邮箱 email','局部掩码','保留首字符与完整域名，@ 前其余字符替换为 *','wangzhenyi1998@qq.com','w************@qq.com','保留域名用于邮箱服务商统计','不可逆'),(7,'医生姓名 doctor_name','保留姓氏掩码','保留姓氏，其余替换为 *','李文博','李**','医生工号已重编码，姓名仅保留姓氏','不可逆'),(8,'就诊人主诉 / 现病史 chief_complaint','文本泛化','去除其中出现的人名、数字、时间细节，只保留症状关键词','患者于3天前无明显诱因出现咳嗽，家属李明陪同就诊','患者无明显诱因出现咳嗽','文本类非结构化字段做通用化处理，避免间接标识','不可逆');
