CREATE TABLE `dim_disease` (
  `disease_id` int NOT NULL COMMENT '疾病ID',
  `diagnosis_code` varchar(16) NOT NULL COMMENT 'ICD-10 编码',
  `diagnosis_name` varchar(128) NOT NULL COMMENT '疾病名称',
  `disease_category` varchar(64) DEFAULT NULL COMMENT '疾病类别',
  `is_infectious` tinyint NOT NULL DEFAULT '0' COMMENT '是否法定传染病',
  `severity` tinyint DEFAULT NULL COMMENT '严重程度1~5',
  `is_chronic` tinyint NOT NULL DEFAULT '0' COMMENT '是否慢性病',
  PRIMARY KEY (`disease_id`),
  KEY `idx_code` (`diagnosis_code`),
  KEY `idx_cat` (`disease_category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='疾病字典表（ICD-10）';
