--
-- Table structure for table `dim_drug`
--

DROP TABLE IF EXISTS `dim_drug`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dim_drug` (
  `drug_id` int NOT NULL COMMENT '药品ID',
  `drug_code` varchar(32) DEFAULT NULL COMMENT '药品编码',
  `drug_name` varchar(128) NOT NULL COMMENT '药品名称',
  `drug_type` varchar(64) DEFAULT NULL COMMENT '药品类别',
  `spec` varchar(64) DEFAULT NULL COMMENT '规格',
  `unit` varchar(16) DEFAULT NULL COMMENT '单位',
  `unit_price` decimal(12,2) DEFAULT NULL COMMENT '单价',
  `manufacturer` varchar(128) DEFAULT NULL COMMENT '生产厂家',
  `is_insurance` tinyint NOT NULL DEFAULT '0' COMMENT '是否医保目录',
  PRIMARY KEY (`drug_id`),
  KEY `idx_type` (`drug_type`),
  KEY `idx_name` (`drug_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='药品维度表';
/*!40101 SET character_set_client = @saved_cs_client */;

