--
-- Table structure for table `rt_crawler_stat`
--

DROP TABLE IF EXISTS `rt_crawler_stat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rt_crawler_stat` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `window_end` datetime NOT NULL COMMENT '窗口结束',
  `period` varchar(16) DEFAULT NULL COMMENT '公报期次 yyyy-MM',
  `disease_name` varchar(128) DEFAULT NULL COMMENT '病种名称',
  `case_cnt` bigint NOT NULL DEFAULT '0' COMMENT '发病数（CDC 公报真实值）',
  `death_cnt` bigint NOT NULL DEFAULT '0' COMMENT '死亡数（CDC 公报真实值）',
  `source` varchar(32) DEFAULT NULL COMMENT '数据来源标记',
  `source_url` varchar(255) DEFAULT NULL COMMENT '公报原文链接',
  `update_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_win` (`window_end`),
  KEY `idx_period` (`period`)
) ENGINE=InnoDB AUTO_INCREMENT=628 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='实时爬虫统计（CDC 公报爬取，Spark Streaming 写入）';
/*!40101 SET character_set_client = @saved_cs_client */;

